import{_ as t,o,c as a,a3 as s}from"./chunks/framework.BlfGB29P.js";const h=JSON.parse('{"title":"Leads — User Guide","description":"","frontmatter":{"head":[["meta",{"property":"og:title","content":"Leads — User Guide | EloSync Docs"}],["meta",{"property":"og:description","content":"Official documentation for the EloSync SaaS Platform."}],["meta",{"property":"og:url","content":"https://docs.elosync.com/user-guide/leads"}],["meta",{"property":"og:image","content":"https://docs.elosync.com/og-image.svg"}],["meta",{"name":"twitter:card","content":"summary_large_image"}],["meta",{"name":"twitter:title","content":"Leads — User Guide | EloSync Docs"}],["meta",{"name":"twitter:description","content":"Official documentation for the EloSync SaaS Platform."}],["meta",{"name":"twitter:image","content":"https://docs.elosync.com/og-image.svg"}],["link",{"rel":"canonical","href":"https://docs.elosync.com/user-guide/leads"}]]},"headers":[],"relativePath":"user-guide/leads.md","filePath":"user-guide/leads.md","lastUpdated":1786995157000}'),n={name:"user-guide/leads.md"};function r(i,e,l,d,g,c){return o(),a("div",null,[...e[0]||(e[0]=[s('<h1 id="leads-—-user-guide" tabindex="-1">Leads — User Guide <a class="header-anchor" href="#leads-—-user-guide" aria-label="Permalink to &quot;Leads — User Guide&quot;">​</a></h1><h2 id="who-can-use-leads" tabindex="-1">Who can use Leads <a class="header-anchor" href="#who-can-use-leads" aria-label="Permalink to &quot;Who can use Leads&quot;">​</a></h2><p>Your workspace must have the <strong>Leads</strong> module installed (included by default on new workspaces). Your role must include the relevant permissions (<code>view</code>, <code>create</code>, <code>update</code>, <code>delete</code>, <code>restore</code>, <code>force.delete</code>, <code>assign</code>, <code>export</code>, <code>import</code>, <code>convert</code> as needed).</p><p>Without <strong>assign</strong>, you only see leads assigned to you.</p><h2 id="page-tour" tabindex="-1">Page tour <a class="header-anchor" href="#page-tour" aria-label="Permalink to &quot;Page tour&quot;">​</a></h2><p>Use the <strong>help</strong> icon in the Leads page header to walk through KPIs, filters, create actions, and the board/table. The first visit may open this tour automatically once; you can re-run it anytime from the same icon.</p><h2 id="board-table" tabindex="-1">Board &amp; table <a class="header-anchor" href="#board-table" aria-label="Permalink to &quot;Board &amp; table&quot;">​</a></h2><p>Open <strong>Leads</strong> from the sidebar. The default view is the <strong>Kanban board</strong> (columns = pipeline stages). Switch to <strong>Table</strong> when you prefer a list.</p><ul><li>Search by name, email, phone, or company</li><li>Each stage column header and its cards use that stage’s color; Stage badges in the table and detail drawer use the same colors</li><li>Filter by stage, status, priority, tag, assignee, and lead value range</li><li>KPI cards summarize totals, pipeline value, follow-ups, and conversion metrics for your scope</li><li>Table and board both show <strong>lead type</strong>, <strong>tags</strong>, the <strong>latest note</strong>, and <strong>next follow-up</strong>; hover a truncated preview to read the full note or follow-up details</li><li><strong>Manage tags</strong> (requires update) opens the workspace tag catalog — create, edit, reorder, delete. Seeded tags include Direct Lead / Company Lead (synced from lead type), Not Contacted (default), Contacted, No Response (auto follow-up after N days), Invalid Number, Not Interested, Not Applied, and Follow Up Later (forces a follow-up when applied)</li><li>Users with <strong>restore</strong> (workspace <strong>admin</strong> by default, plus owner) can filter <strong>Active / Include deleted / Deleted only</strong>, then <strong>Restore</strong> a soft-deleted lead from the row menu</li><li><strong>Delete permanently</strong> (force delete) requires <code>leads.force.delete</code> — granted to the workspace <strong>owner</strong> by default (or any role you assign it to)</li></ul><h2 id="create-edit" tabindex="-1">Create &amp; edit <a class="header-anchor" href="#create-edit" aria-label="Permalink to &quot;Create &amp; edit&quot;">​</a></h2><ol><li>Click <strong>New lead</strong>, or press <code>N</code> when not typing in a field (requires <strong>create</strong>; browsers reserve <code>Ctrl+N</code> for a new window)</li><li>Enter name (required), <strong>lead type</strong> (Direct or Company), and optional contact / company / source / <strong>lead value</strong> / priority / status</li><li>Optionally set stage, tags, and assignee (assignee requires <strong>assign</strong>). Applying Follow Up Later requires a follow-up title and due date</li><li>Save</li></ol><p>Press <code>⌘F</code> / <code>Ctrl+F</code> to focus the Leads search box (filters this list only). Edit from the row menu or the detail drawer.</p><h2 id="high-priority-dashboard" tabindex="-1">High Priority (dashboard) <a class="header-anchor" href="#high-priority-dashboard" aria-label="Permalink to &quot;High Priority (dashboard)&quot;">​</a></h2><p>With <strong>update</strong> permission, open a lead’s detail drawer and click <strong>Mark High Priority</strong> on Overview. That sets priority to <strong>High</strong>; click again to clear it. If you marked High from another priority in this browser tab, clear <strong>restores that previous priority</strong> (for example Urgent → High → Urgent). If High was set elsewhere and no restore value is known, clear falls back to <strong>Medium</strong>.</p><p>The Dashboard <strong>High Priority</strong> widget lists open-pipeline leads with priority <strong>High</strong> only. <strong>Urgent is intentionally excluded</strong> from that widget (use the Leads priority filter for Urgent). Existing Urgent open deals that previously appeared on the widget will leave the card after this change until marked High.</p><h2 id="pipeline-vs-status-vs-tags" tabindex="-1">Pipeline vs status vs tags <a class="header-anchor" href="#pipeline-vs-status-vs-tags" aria-label="Permalink to &quot;Pipeline vs status vs tags&quot;">​</a></h2><ul><li><strong>Stage</strong> — where the lead sits in the sales pipeline (New … Won / Lost). Drag a card on the board to move stages — the change saves immediately (no drawer). You can also change stage from the detail drawer and <strong>Save</strong>.</li><li><strong>Status</strong> — lifecycle state managed separately: Active, Waiting, On hold, Closed, Archived. Changing stage does <strong>not</strong> automatically change status.</li><li><strong>Tags</strong> — multi-select disposition labels. Applying tags never changes stage or status. No Response schedules an auto follow-up using the tag’s day count (workspace timezone).</li><li><strong>Lead type</strong> — Direct or Company. Saved on the lead and mirrored by the system tags Direct Lead / Company Lead (only one type tag at a time).</li></ul><h2 id="assignment" tabindex="-1">Assignment <a class="header-anchor" href="#assignment" aria-label="Permalink to &quot;Assignment&quot;">​</a></h2><p>Users with <strong>assign</strong> can set or clear the assignee. Assignment changes are recorded in <strong>Assignment history</strong>. The assignee receives an in-app realtime notification when someone else assigns them. Lead-assignment email is disabled in v1.</p><p><strong>Eligible assignees</strong> exclude:</p><ul><li>Workspace owners (<code>superadmin</code>)</li><li>Suspended users</li><li>Users flagged <strong>Exclude from lead assignment</strong> in Administration → Users (create/edit)</li></ul><p>Those users do not appear in lead assignee pickers and are skipped by import auto-distribute and bulk equal distribute. A lead already assigned to someone who is later flagged can still be kept or cleared from the lead drawer.</p><p><strong>Receive website leads</strong> is a separate opt-in for the custom webhook website-recipient pool when an endpoint has automatic assignment enabled. It does <strong>not</strong> remove users from assignee pickers or equal distribute.</p><p>When a lead is assigned or reassigned, the assignee’s <strong>Default lead commission %</strong> (set in Administration → Users) is copied onto the lead as a read-only <strong>Commission rate</strong> for reporting. Unassign clears it. This is display/export only — EloSync does not calculate payouts.</p><h2 id="notes-follow-ups" tabindex="-1">Notes &amp; follow-ups <a class="header-anchor" href="#notes-follow-ups" aria-label="Permalink to &quot;Notes &amp; follow-ups&quot;">​</a></h2><ul><li><strong>Notes</strong> — free-form history on the lead. Type <code>@</code> to mention a teammate (the composer shows their name; the system keeps the user id for notifications). They get an in-app notification (and optional email if <strong>Settings → Notifications → Mentioned in a lead note</strong> is on)</li><li><strong>Follow-ups</strong> — titled reminders with due dates in the workspace <strong>Timezone</strong> (Settings → General); edit/reschedule or complete when done</li><li>Assignees receive notifications when a follow-up is created for them (by someone else) and when due/overdue reminders run (workspace-local “today”)</li><li><strong>Inactivity alerts</strong> — when an assigned open lead has no meaningful activity for the configured number of Mon–Sat working days (Settings → Leads; default 3), the assignee is notified. Department managers (or workspace owners if none) receive an escalation alert. Sundays do not count. Notes, follow-ups, stage/status changes, CRM activities, and tag changes reset the timer; assignment alone does not.</li></ul><h2 id="whatsapp-communication-templates" tabindex="-1">WhatsApp (Communication Templates) <a class="header-anchor" href="#whatsapp-communication-templates" aria-label="Permalink to &quot;WhatsApp (Communication Templates)&quot;">​</a></h2><p>When the <strong>Communication Templates</strong> module is installed and you have <strong>use</strong> permission:</p><ol><li>Open a lead that has a phone number</li><li>Click <strong>WhatsApp</strong> next to the phone</li><li>Choose a template, preview the filled message, then <strong>Open WhatsApp</strong></li></ol><p>WhatsApp opens with the message pre-filled. EloSync does not send the message for you. See <a href="/user-guide/communication-templates">Communication Templates</a>.</p><h2 id="convert" tabindex="-1">Convert <a class="header-anchor" href="#convert" aria-label="Permalink to &quot;Convert&quot;">​</a></h2><p>Users with <strong>convert</strong> can convert a lead from the detail drawer. Behavior depends on which Marketplace modules are installed:</p><ul><li><strong>Contacts</strong> — creates a linked Contact from lead fields (name, email, phone, job title) with lifecycle <strong>On Boarded Clients</strong>. Requires <code>contacts.create</code>. No separate contact form.</li><li><strong>Companies</strong> — when the lead has a company name, creates a Company or reuses an existing one (case-insensitive name match) and links it to the Contact. Requires <code>companies.create</code> when a new company must be created.</li><li><strong>Opportunities</strong> (optional) — check <strong>Also create an opportunity</strong>, enter a name (defaults to the lead name), and optionally an amount (defaults from lead value). Requires <code>opportunities.create</code>. The opportunity is linked to the lead, contact, and company when those exist.</li></ul><p>The lead is stamped with <code>converted_at</code>, status becomes Closed, and activity is recorded. After convert, the drawer shows <strong>View contact</strong> / <strong>View company</strong> / <strong>View opportunity</strong> links when those records were created and you can view them.</p><p>If Contacts is not installed, convert still closes the lead (<code>converted_at</code> / Closed) without creating a contact. Company and opportunity can still be created when those modules are installed.</p><p>Lifecycle on contacts is independent of soft-delete (trash). See <a href="/user-guide/contacts">Contacts</a>.</p><h2 id="export" tabindex="-1">Export <a class="header-anchor" href="#export" aria-label="Permalink to &quot;Export&quot;">​</a></h2><p>Users with <strong>export</strong> can download the current filtered set as <strong>CSV</strong> or <strong>XLSX</strong> (includes <strong>Commission Rate %</strong> when the lead is assigned).</p><h2 id="import" tabindex="-1">Import <a class="header-anchor" href="#import" aria-label="Permalink to &quot;Import&quot;">​</a></h2><p>Users with <strong>import</strong> can bulk-load leads from <strong>CSV</strong> or <strong>XLSX</strong>:</p><ol><li>Open <strong>Import</strong> and download a sample template if needed (<strong>CSV</strong> or <strong>XLSX</strong> — both include a <strong>Note</strong> column with a sample value)</li><li>Upload a file (drag &amp; drop or browse)</li><li>Map spreadsheet columns to lead fields (Name is required; optional <strong>Note</strong> creates a first note on create, or appends a note on <strong>Update existing</strong>)</li><li>Choose unique fields (<strong>Email</strong> / <strong>Phone</strong>) and duplicate behavior (<strong>Skip</strong>, <strong>Update existing</strong>, or <strong>Keep duplicate</strong>)</li><li>Preview counts and validation errors (nothing is written yet)</li><li>Start the import — it runs in the background; watch progress until complete</li></ol><p>When another lead with the same email or phone was already created <strong>today</strong> (workspace timezone from Settings → General), EloSync applies the <strong>Duplicate</strong> tag and notifies the existing lead’s assignee, creator, and the person importing — even if the row is skipped. Manual create and inbound webhooks follow the same same-day rule (manual create still adds the new lead).</p><p><strong>Update existing</strong> also requires the <strong>update</strong> permission.</p><p><strong>Automatically distribute</strong> (equal split) is available only when you have <strong>assign</strong> and you are a <strong>department manager</strong> of at least one active department. Newly created leads are shared equally among eligible members of your managed department(s) (owners and users marked <strong>Exclude from lead assignment</strong> are skipped). Non-managers cannot enable this mode.</p><p>Use <strong>Import history</strong> to review past imports, download the original file, <strong>failed_records.csv</strong>, or <strong>error_report.csv</strong>. Fix failed rows and upload again.</p><h2 id="integrations-webhooks" tabindex="-1">Integrations (webhooks) <a class="header-anchor" href="#integrations-webhooks" aria-label="Permalink to &quot;Integrations (webhooks)&quot;">​</a></h2><p>Users with <strong>manage integrations</strong> can open <strong>Integrations</strong> from the Leads page.</p><p><strong>Custom webhooks</strong> — create endpoints for Zapier, website forms, etc. Use <strong>Copy URL</strong> and <strong>Copy JSON</strong> on each endpoint: the JSON is an example POST body (<code>name</code>, <code>email</code>, <code>phone</code>, …; extras under <code>custom_fields</code>) with that endpoint’s default source filled in. Authenticate separately with the API key (Bearer) or HMAC — do not put secrets in the page. Each endpoint can enable <strong>Assign to website recipients</strong>. When on, new leads from that webhook are shared equally among users who are eligible assignees <strong>and</strong> have <strong>Receive website leads</strong> enabled in Administration → Users. If nobody is in that pool, the lead stays unassigned (ingest still succeeds). Meta Lead Ads does not use this pool.</p><h2 id="activity-timeline" tabindex="-1">Activity timeline <a class="header-anchor" href="#activity-timeline" aria-label="Permalink to &quot;Activity timeline&quot;">​</a></h2><p>The <strong>Activity</strong> tab shows create, update, stage, assignment, note, follow-up, convert, and related events.</p>',50)])])}const u=t(n,[["render",r]]);export{h as __pageData,u as default};
